<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>School Bus Tracking Admin</title>
    <style>
        body { margin: 0; font-family: system-ui, sans-serif; color: #1f2937; background: #f1f5f9; }
        .app { display: grid; grid-template-columns: 220px 1fr; min-height: 100vh; }
        aside { padding: 24px 16px; color: white; background: #3c3637; } aside h1 { font-size: 20px; } nav a { display:block; padding: 12px; margin: 5px 0; color:#ddd6d6; text-decoration:none; border-radius:8px; } nav a.active { color:#111827; background:#ffbd2e; }
        main { padding: 28px; } .kpis, .grid { display:grid; grid-template-columns:repeat(12, 1fr); gap:16px; } .kpi, .card { padding:18px; border-radius:8px; background:#fff; box-shadow:0 4px 12px rgba(15,23,42,.08); } .kpi { grid-column:span 3; } .card { grid-column:span 4; } .wide { grid-column:span 8; } .full { grid-column:1/-1; }
        label { display:block; margin-top:9px; font-size:13px; font-weight:700; } input, select { width:100%; padding:9px; border:1px solid #cbd5e1; border-radius:6px; box-sizing:border-box; } button { margin-top:14px; padding:10px 14px; border:0; border-radius:6px; font-weight:700; background:#ffbd2e; cursor:pointer; } table { width:100%; border-collapse:collapse; margin-top:12px; background:#fff; } th,td { padding:10px; text-align:left; border-bottom:1px solid #e5e7eb; } th { color:#64748b; font-size:12px; } .flash { padding:12px; margin-bottom:16px; border-radius:6px; background:#dcfce7; color:#166534; } .error { padding:12px; margin-bottom:16px; border-radius:6px; background:#fee2e2; color:#991b1b; } .map { min-height:400px; padding:24px; background:#dbeafe; border-radius:8px; } .pill { padding:3px 8px; border-radius:999px; background:#dbeafe; color:#1d4ed8; }
        @media(max-width:900px){ .app{grid-template-columns:1fr} aside{padding:16px} nav{display:flex;overflow:auto} nav a{white-space:nowrap}.kpi,.card,.wide{grid-column:1/-1} }
    </style>
</head>
<body>
<?php $menu = ['dashboard'=>'Dashboard','database'=>'Database','route'=>'Routes','tracking'=>'Tracking','requests'=>'Trips','settings'=>'Settings']; ?>
<div class="app"><aside><h1>LittleMove School</h1><nav><?php foreach ($menu as $key => $label): ?><a class="<?= $section === $key ? 'active' : '' ?>" href="<?= site_url('admin/' . ($key === 'dashboard' ? 'dashboard' : $key)) ?>"><?= esc($label) ?></a><?php endforeach ?></nav></aside><main>
    <h2><?= esc(ucfirst($section)) ?></h2>
    <?php if (session('status')): ?><div class="flash"><?= esc(session('status')) ?></div><?php endif ?>
    <?php if (session('error')): ?><div class="error"><?= esc(session('error')) ?></div><?php endif ?>

    <?php if ($section === 'dashboard'): ?><div class="kpis"><div class="kpi">Buses<strong><?= count($buses) ?></strong></div><div class="kpi">Drivers<strong><?= count($drivers) ?></strong></div><div class="kpi">Students<strong><?= count($students) ?></strong></div><div class="kpi">Active trips<strong><?= esc($report['active_trips']) ?></strong></div></div><div class="card full"><h3>Ongoing Trips</h3><table><tr><th>Bus</th><th>Route</th><th>Status</th><th>ETA</th></tr><?php foreach ($activeTrips as $trip): ?><tr><td><?= esc($trip['registration_number']) ?></td><td><?= esc($trip['route_name'] ?? 'No route') ?></td><td><span class="pill"><?= esc($trip['status']) ?></span></td><td><?= esc($trip['predicted_eta_minutes'] ?? '-') ?> min</td></tr><?php endforeach ?></table><p>Average ETA variance: <?= esc($report['avg_eta_variance']) ?> min · Average duration: <?= esc($report['avg_duration']) ?> min</p></div><?php endif ?>

    <?php if ($section === 'database'): ?><div class="grid"><div class="card"><h3>Add Bus</h3><form method="post" action="<?= site_url('admin/buses') ?>"><?= csrf_field() ?><label>Registration</label><input name="registration_number" required><label>Device ID</label><input name="device_id" required><label>Device Token</label><input name="device_token"><label>Capacity</label><input name="capacity" type="number" value="30" required><label>Driver</label><select name="driver_id"><option value="">No driver</option><?php foreach($drivers as $driver): ?><option value="<?= $driver['id'] ?>"><?= esc($driver['name']) ?></option><?php endforeach ?></select><button>Save Bus</button></form></div><div class="card"><h3>Add Driver</h3><form method="post" action="<?= site_url('admin/drivers') ?>"><?= csrf_field() ?><label>Name</label><input name="name" required><label>Email</label><input name="email" type="email" required><label>Password</label><input name="password"><button>Save Driver</button></form></div><div class="card"><h3>Add Student</h3><form method="post" action="<?= site_url('admin/students') ?>"><?= csrf_field() ?><label>Admission Number</label><input name="admission_number" required><label>First name</label><input name="first_name" required><label>Last name</label><input name="last_name" required><label>Class</label><input name="class_name"><button>Save Student</button></form></div><div class="card full"><h3>Buses</h3><table><tr><th>Bus</th><th>Driver</th><th>Routes</th><th>Latest GPS</th></tr><?php foreach($buses as $bus): ?><tr><td><?= esc($bus['registration_number']) ?><br><small><?= esc($bus['device_id']) ?></small></td><td><?= esc($bus['driver_name'] ?? 'No driver') ?></td><td><?= esc(implode(', ', array_column($bus['routes'], 'name'))) ?></td><td><?= $bus['latest_location'] ? esc($bus['latest_location']['latitude'] . ', ' . $bus['latest_location']['longitude']) : 'No GPS yet' ?></td></tr><?php endforeach ?></table></div></div><?php endif ?>

    <?php if ($section === 'route'): ?><div class="grid"><div class="card"><h3>Add Route</h3><form method="post" action="<?= site_url('admin/routes') ?>"><?= csrf_field() ?><label>Name</label><input name="name" required><label>Start</label><input name="start_location"><label>End</label><input name="end_location"><label>Bus</label><select name="bus_id"><option value="">No bus</option><?php foreach($buses as $bus): ?><option value="<?= $bus['id'] ?>"><?= esc($bus['registration_number']) ?></option><?php endforeach ?></select><button>Save Route</button></form></div><div class="card"><h3>Add Stop</h3><form method="post" action="<?= site_url('admin/stops') ?>"><?= csrf_field() ?><label>Route</label><select name="route_id" required><?php foreach($routes as $route): ?><option value="<?= $route['id'] ?>"><?= esc($route['name']) ?></option><?php endforeach ?></select><label>Name</label><input name="name" required><label>Latitude</label><input name="latitude" required><label>Longitude</label><input name="longitude" required><label>Order</label><input name="stop_order" type="number" required><button>Save Stop</button></form></div><div class="card"><h3>Assign Student</h3><form method="post" action="<?= site_url('admin/assignments') ?>"><?= csrf_field() ?><label>Student</label><select name="student_id" required><?php foreach($students as $student): ?><option value="<?= $student['id'] ?>"><?= esc($student['first_name'].' '.$student['last_name']) ?></option><?php endforeach ?></select><label>Bus</label><select name="bus_id" required><?php foreach($buses as $bus): ?><option value="<?= $bus['id'] ?>"><?= esc($bus['registration_number']) ?></option><?php endforeach ?></select><label>Pickup stop</label><select name="bus_stop_id"><option value="">No stop</option><?php foreach($stops as $stop): ?><option value="<?= $stop['id'] ?>"><?= esc($stop['name']) ?></option><?php endforeach ?></select><button>Assign</button></form></div><div class="card full"><h3>Routes</h3><table><tr><th>Name</th><th>Start</th><th>End</th><th>Stops</th></tr><?php foreach($routes as $route): ?><tr><td><?= esc($route['name']) ?></td><td><?= esc($route['start_location']) ?></td><td><?= esc($route['end_location']) ?></td><td><?= esc(implode(', ', array_column($route['stops'], 'name'))) ?></td></tr><?php endforeach ?></table></div></div><?php endif ?>

    <?php if ($section === 'requests'): ?><div class="grid"><div class="card"><h3>Create Trip</h3><form method="post" action="<?= site_url('admin/trips') ?>"><?= csrf_field() ?><label>Bus</label><select name="bus_id" required><?php foreach($buses as $bus): ?><option value="<?= $bus['id'] ?>"><?= esc($bus['registration_number']) ?></option><?php endforeach ?></select><label>Route</label><select name="route_id"><option value="">No route</option><?php foreach($routes as $route): ?><option value="<?= $route['id'] ?>"><?= esc($route['name']) ?></option><?php endforeach ?></select><label>Status</label><select name="status"><option>scheduled</option><option>active</option><option>completed</option></select><label>ETA minutes</label><input name="predicted_eta_minutes" type="number" value="45"><button>Save Trip</button></form></div><div class="card wide"><h3>Ongoing Trips</h3><table><tr><th>Bus</th><th>Route</th><th>Status</th><th>Complete</th></tr><?php foreach($activeTrips as $trip): ?><tr><td><?= esc($trip['registration_number']) ?></td><td><?= esc($trip['route_name'] ?? 'No route') ?></td><td><?= esc($trip['status']) ?></td><td><form method="post" action="<?= site_url('admin/trips/'.$trip['id'].'/complete') ?>"><?= csrf_field() ?><input name="actual_duration_minutes" type="number" value="<?= esc($trip['predicted_eta_minutes'] ?? 45) ?>" required><button>Done</button></form></td></tr><?php endforeach ?></table></div></div><?php endif ?>

    <?php if ($section === 'tracking'): ?><div class="map"><h3>Live locations</h3><?php foreach($buses as $bus): ?><p><strong><?= esc($bus['registration_number']) ?></strong>: <?= $bus['latest_location'] ? esc($bus['latest_location']['latitude'].', '.$bus['latest_location']['longitude'].' at '.$bus['latest_location']['recorded_at']) : 'No GPS location yet' ?></p><?php endforeach ?><p>Mobile API: <code>/api/buses/{id}/location</code></p></div><?php endif ?>
    <?php if ($section === 'settings'): ?><div class="card"><h3>Completed trips</h3><table><tr><th>Bus</th><th>Route</th><th>Duration</th><th>Variance</th></tr><?php foreach($completedTrips as $trip): ?><tr><td><?= esc($trip['registration_number']) ?></td><td><?= esc($trip['route_name'] ?? 'No route') ?></td><td><?= esc($trip['actual_duration_minutes'] ?? '-') ?> min</td><td><?= esc($trip['eta_variance_minutes'] ?? '-') ?> min</td></tr><?php endforeach ?></table></div><?php endif ?>
</main></div></body></html>
